import java.io.*;
import java.nio.charset.StandardCharsets;

public class StreamHierarchyDemo {

    public void readConfigFile(String path) throws IOException {
        // Base: FileInputStream reads raw bytes from file
        var fileInput = new FileInputStream(path);

        // Decorator: BufferedInputStream adds buffering (8KB default)
        var bufferedInput = new BufferedInputStream(fileInput);

        // Bridge: InputStreamReader converts bytes to characters
        var reader = new InputStreamReader(bufferedInput, StandardCharsets.UTF_8);

        // Decorator: BufferedReader adds line-by-line reading
        var bufferedReader = new BufferedReader(reader);

        String line;
        while ((line = bufferedReader.readLine()) != null) {
            System.out.println("Config: " + line);
        }

        bufferedReader.close(); // Closes entire decorator chain
    }

    // Modern approach: Files API does the wrapping for you
    public void modernRead(String path) throws IOException {
        var lines = Files.readAllLines(Path.of(path), StandardCharsets.UTF_8);
        lines.forEach(System.out::println);
    }
}

import java.io.*;
import java.nio.file.*;

public class ResourceManagementDemo {

    // WRONG: Resource leak if readLine() throws exception
    public void leakyRead(String path) throws IOException {
        var reader = new BufferedReader(new FileReader(path));
        String line = reader.readLine();
        System.out.println(line);
        reader.close(); // Never reached if readLine() throws
    }

    // CORRECT: try-with-resources auto-closes even on exception
    public void safeRead(String path) throws IOException {
        try (var reader = Files.newBufferedReader(Path.of(path))) {
            String line = reader.readLine();
            System.out.println(line);
        } // reader.close() called automatically here
    }

    // Multiple resources: all closed in reverse order
    public void copyFile(String source, String dest) throws IOException {
        try (var input = new FileInputStream(source);
             var output = new FileOutputStream(dest)) {

            input.transferTo(output); // Java 9+ efficient copy

        } // Both streams closed automatically, output first then input
    }
}

import java.io.*;
import java.nio.file.*;

public class ReadWritePatterns {

    // INEFFICIENT: reads one byte at a time (8000 system calls for 8KB)
    public void slowRead(String path) throws IOException {
        try (var input = new FileInputStream(path)) {
            int byteValue;
            while ((byteValue = input.read()) != -1) { // Check for -1 end marker
                System.out.print((char) byteValue);
            }
        }
    }

    // EFFICIENT: bulk reads into 8KB buffer (one system call per 8KB)
    public void fastRead(String path) throws IOException {
        try (var input = new FileInputStream(path)) {
            var buffer = new byte[8192]; // 8KB buffer
            int bytesRead;
            while ((bytesRead = input.read(buffer)) != -1) {
                System.out.write(buffer, 0, bytesRead); // Write only bytes read
            }
        }
    }

    // Character streams: line-by-line reading
    public void readLines(String path) throws IOException {
        try (var reader = Files.newBufferedReader(Path.of(path))) {
            String line;
            while ((line = reader.readLine()) != null) { // Check for null
                System.out.println("Line: " + line);
            }
        }
    }
}
